MOD = 998244353

def solve():
	n = int(input())
	ans = 0
	arr = []
	for i in range(n):
		a = list(input().split())
		if len(a) == 2:
			arr.append(int(a[1]))
		else:
			arr.append(0)
	for cur in range(n):
		if arr[cur]:
			dp = [0] * (n + 1)
			dp[0] = 1
			for (j, a) in enumerate(arr):
				if j == cur:
					dp = [0] + dp[:n]
				elif a == 0:
					dp[0] = (2 * dp[0] + dp[1]) % MOD
					for i in range(1, n):
						dp[i] = (dp[i] + dp[i + 1]) % MOD
				elif a < arr[cur] or (a == arr[cur] and j < cur):
					if j < cur:
						for i in range(n, 0, -1):
							dp[i] = (dp[i - 1] + dp[i]) % MOD
					else:
						for i in range(n, 1, -1):
							dp[i] = (dp[i - 1] + dp[i]) % MOD
						dp[0] = dp[0] * 2 % MOD
				else:
					dp = [d * 2 % MOD for d in dp]
			ans = (ans + (sum(dp) - dp[0]) * arr[cur]) % MOD
	return ans
import sys
input = lambda : sys.stdin.readline().rstrip()
print(solve())
